async function main() {
  const nameToUrl: Record<string, string> = {};

  for (const spec of FLAVORS) {
    const srcPath = path.join(ARTIFACT_DIR, BASE_FILES[spec.base]);
    let pipeline = sharp(srcPath);

    if (spec.crop) {
      pipeline = pipeline.extract(spec.crop);
    }
    if (spec.flop) {
      pipeline = pipeline.flop();
    }

    pipeline = pipeline.resize(600, 600, { fit: "cover", position: "centre" });

    if (spec.modulate) {
      pipeline = pipeline.modulate(spec.modulate);
    } else {
      pipeline = pipeline.modulate({ saturation: 1.05 });
    }

    if (spec.overlayGradient) {
      const { colorTop, colorBottom, opacity } = spec.overlayGradient;
      const svg = Buffer.from(
        `<svg width="600" height="600" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <linearGradient id="g" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stop-color="${colorTop}" stop-opacity="${opacity}" />
              <stop offset="100%" stop-color="${colorBottom}" stop-opacity="${opacity * 1.15}" />
            </linearGradient>
          </defs>
          <rect width="600" height="600" fill="url(#g)" style="mix-blend-mode: soft-light;" />
        </svg>`,
      );
      pipeline = pipeline.composite([{ input: svg, blend: "soft-light" }]);
    }

    const webpBuf = await pipeline
      .sharpen({ sigma: 0.8, m1: 0.4, m2: 1.5 })
      .webp({ quality: 86, alphaQuality: 100 })
      .toBuffer();

    const hash = crypto.createHash("sha256").update(webpBuf).digest("hex").slice(0, 24);
    const fileName = `${hash}.webp`;
    const publicUrl = `/merit-menus/${fileName}`;

    for (const dir of PUBLIC_DIRS) {
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(path.join(dir, fileName), webpBuf);
    }

    for (const n of spec.names) {
      nameToUrl[n] = publicUrl;
    }
    console.log(`Processed Nargile [${spec.slug}] -> ${publicUrl} (${(webpBuf.length / 1024).toFixed(1)} KB)`);
  }

  // Update merit-menus.json in both worktree and main repo
  const jsonPaths = [
    "C:/Users/Erkan/.gemini/antigravity/worktrees/qrmenu/match_menus_outlets/merit/prisma/seed/data/merit-menus.json",
    "D:/PROJECTS/qrmenu/merit/prisma/seed/data/merit-menus.json",
  ];

  let updatedCount = 0;
  for (const jp of jsonPaths) {
    const data = JSON.parse(fs.readFileSync(jp, "utf8"));
    for (const outlet of data.outlets) {
      for (const item of outlet.items) {
        if (item.catPath[0] === "NARGİLE" && nameToUrl[item.name]) {
          item.imageUrl = nameToUrl[item.name];
          updatedCount++;
        }
      }
    }
    fs.writeFileSync(jp, JSON.stringify(data, null, 2), "utf8");
  }
  console.log(`Updated ${updatedCount / 2} Nargile items across merit-menus.json`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
